insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$perkins-diesel-generator-10-200kva$q$,$q$Perkins Diesel Generator 10–200 kVA$q$,$q$مولد ديزل بيركنز 10–200 كيلو فولت أمبير$q$,10,200,$q$Perkins$q$,$q$diesel$q$,$q$Compact Perkins 400 and 1100 Series powered generator sets for villas, shops, telecom sites and light commercial standby. Low fuel consumption, wide parts availability across the GCC and fast delivery from our SAIF Zone warehouse.$q$,$q$مولدات بمحركات بيركنز من الفئة 400 و1100 للفلل والمحلات ومواقع الاتصالات والاستخدام التجاري الاحتياطي الخفيف. استهلاك وقود منخفض، قطع غيار متوفرة في كل دول الخليج، وتسليم سريع من مستودعنا في المنطقة الحرة بالشارقة.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"10 – 200 kVA (prime / standby)","value_ar":"10 – 200 ك.ف.أ (أساسي / احتياطي)"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Perkins 400 / 1100 Series, water-cooled","value_ar":"بيركنز الفئة 400 / 1100، تبريد بالماء"},{"label_en":"Alternator","label_ar":"المولّد (الدينامو)","value_en":"Brushless, H-class insulation","value_ar":"بدون فرش، عزل فئة H"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"},{"label_en":"Fuel tank","label_ar":"خزان الوقود","value_en":"8–12 hour base tank","value_ar":"خزان قاعدي يكفي 8–12 ساعة"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],10,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$perkins-diesel-generator-250-2500kva$q$,$q$Perkins Industrial Generator 250–2500 kVA$q$,$q$مولد بيركنز صناعي 250–2500 كيلو فولت أمبير$q$,250,2500,$q$Perkins$q$,$q$diesel$q$,$q$Heavy-duty Perkins 1300, 2000 and 4000 Series sets for factories, hospitals, data rooms and towers. Supplied as containerised or canopy units, ready for synchronisation and remote monitoring.$q$,$q$مولدات بيركنز للخدمة الشاقة من الفئات 1300 و2000 و4000 للمصانع والمستشفيات وغرف البيانات والأبراج. تتوفر داخل حاويات أو كبائن، وجاهزة للتزامن والمراقبة عن بُعد.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"250 – 2500 kVA","value_ar":"250 – 2500 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Perkins 1300 / 2000 / 4000 Series","value_ar":"بيركنز الفئات 1300 / 2000 / 4000"},{"label_en":"Alternator","label_ar":"المولّد (الدينامو)","value_en":"Brushless, PMG excitation option","value_ar":"بدون فرش، مع خيار إثارة PMG"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"},{"label_en":"Parallel operation","label_ar":"التشغيل المتوازي","value_en":"Sync-ready controller","value_ar":"وحدة تحكم جاهزة للتزامن"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-container.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],20,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$cummins-diesel-generator-20-500kva$q$,$q$Cummins Diesel Generator 20–500 kVA$q$,$q$مولد ديزل كمنز 20–500 كيلو فولت أمبير$q$,20,500,$q$Cummins$q$,$q$diesel$q$,$q$Cummins-engined generator sets known for strong load acceptance — a common choice for construction sites, commercial buildings and rental fleets in the UAE, Saudi Arabia and Iraq.$q$,$q$مولدات بمحركات كمنز معروفة بقدرتها العالية على تحمّل الأحمال المفاجئة، وهي خيار شائع لمواقع البناء والمباني التجارية وأساطيل التأجير في الإمارات والسعودية والعراق.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"20 – 500 kVA","value_ar":"20 – 500 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Cummins 4B / 6B / 6C / QSL / QSZ family","value_ar":"كمنز عائلة 4B / 6B / 6C / QSL / QSZ"},{"label_en":"Alternator","label_ar":"المولّد (الدينامو)","value_en":"Brushless, AVR ±1%","value_ar":"بدون فرش، منظم جهد ±1%"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],30,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$cummins-diesel-generator-550-2500kva$q$,$q$Cummins Heavy-Duty Generator 550–2500 kVA$q$,$q$مولد كمنز للخدمة الشاقة 550–2500 كيلو فولت أمبير$q$,550,2500,$q$Cummins$q$,$q$diesel$q$,$q$High-horsepower Cummins QSK / KTA sets for mission-critical standby and continuous prime power in mining, oil & gas and utilities. Available containerised with bulk fuel and synchronising gear.$q$,$q$مولدات كمنز عالية القدرة من فئة QSK / KTA للطاقة الاحتياطية الحرجة والتشغيل الأساسي المستمر في التعدين والنفط والغاز والمرافق. متوفرة داخل حاويات مع خزانات وقود كبيرة ومعدات تزامن.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"550 – 2500 kVA","value_ar":"550 – 2500 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Cummins KTA / QSK series","value_ar":"كمنز فئة KTA / QSK"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"},{"label_en":"Duty","label_ar":"نوع التشغيل","value_en":"Standby, prime and continuous ratings","value_ar":"احتياطي، أساسي ومستمر"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-container.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],40,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$kubota-silent-generator-10-40kva$q$,$q$Kubota Silent Generator 10–40 kVA$q$,$q$مولد كوبوتا صامت 10–40 كيلو فولت أمبير$q$,10,40,$q$Kubota$q$,$q$diesel$q$,$q$Ultra-quiet Kubota-powered sets for villas, clinics, retail units and events where noise matters. Compact footprint, single or three-phase output.$q$,$q$مولدات هادئة جداً بمحركات كوبوتا للفلل والعيادات والمحلات والفعاليات حيث يهم مستوى الضوضاء. حجم صغير وخرج أحادي أو ثلاثي الفاز.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"10 – 40 kVA","value_ar":"10 – 40 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Kubota D / V series, water-cooled","value_ar":"كوبوتا فئة D / V، تبريد بالماء"},{"label_en":"Noise level","label_ar":"مستوى الضوضاء","value_en":"From 62 dB(A) @ 7 m (model dependent)","value_ar":"من 62 ديسيبل على بعد 7 م (حسب الموديل)"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V 3-phase or 230 V single-phase, 50 Hz","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$]::text[],50,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$volvo-penta-generator-80-700kva$q$,$q$Volvo Penta Generator 80–700 kVA$q$,$q$مولد فولفو بنتا 80–700 كيلو فولت أمبير$q$,80,700,$q$Volvo Penta$q$,$q$diesel$q$,$q$Volvo Penta TAD-series gensets offering excellent fuel economy and clean emissions for hotels, commercial towers and marine-adjacent facilities.$q$,$q$مولدات فولفو بنتا من فئة TAD توفر كفاءة عالية في استهلاك الوقود وانبعاثات منخفضة، مناسبة للفنادق والأبراج التجارية والمنشآت القريبة من البحر.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"80 – 700 kVA","value_ar":"80 – 700 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Volvo Penta TAD series","value_ar":"فولفو بنتا فئة TAD"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],60,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$chinese-engine-generator-series-20-1000kva$q$,$q$Chinese Engine Series Generator 20–1000 kVA$q$,$q$مولدات بمحركات صينية 20–1000 كيلو فولت أمبير$q$,20,1000,$q$Chinese Engine Series$q$,$q$diesel$q$,$q$Value-engineered generator sets built on proven Chinese engine platforms — the budget-conscious option for construction, agriculture and backup power where total cost of ownership comes first.$q$,$q$مولدات اقتصادية مبنية على منصات محركات صينية مجرّبة، وهي الخيار الأنسب من حيث التكلفة لمواقع البناء والزراعة والطاقة الاحتياطية.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"20 – 1000 kVA","value_ar":"20 – 1000 ك.ف.أ"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Proven Chinese engine platforms (brand confirmed per quote)","value_ar":"منصات محركات صينية مجرّبة (تحدد العلامة في عرض السعر)"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-open.svg$q$,$q$/images/products/generator-canopy.svg$q$]::text[],70,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$gas-generator-50-1000kva$q$,$q$Natural Gas Generator 50–1000 kVA$q$,$q$مولد يعمل بالغاز الطبيعي 50–1000 كيلو فولت أمبير$q$,50,1000,null,$q$gas$q$,$q$Natural-gas and LPG generator sets for sites with piped gas — lower running cost and emissions for continuous-duty industrial and commercial applications.$q$,$q$مولدات تعمل بالغاز الطبيعي أو الغاز المسال للمواقع المتصلة بشبكة غاز، بتكلفة تشغيل وانبعاثات أقل للتطبيقات الصناعية والتجارية ذات التشغيل المستمر.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"50 – 1000 kVA","value_ar":"50 – 1000 ك.ف.أ"},{"label_en":"Fuel","label_ar":"الوقود","value_en":"Natural gas / LPG","value_ar":"غاز طبيعي / غاز مسال"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 فاز، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-container.svg$q$]::text[],80,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$hybrid-battery-generator-20-200kva$q$,$q$Hybrid Generator + Battery System 20–200 kVA$q$,$q$نظام مولد هجين مع بطاريات 20–200 كيلو فولت أمبير$q$,20,200,null,$q$hybrid$q$,$q$Diesel generator paired with a lithium battery bank and smart controller. The engine only runs when needed, cutting fuel use and maintenance on low- or variable-load sites.$q$,$q$مولد ديزل مقترن بمجموعة بطاريات ليثيوم ووحدة تحكم ذكية، يعمل المحرك فقط عند الحاجة فيقلل استهلاك الوقود والصيانة في المواقع ذات الأحمال المنخفضة أو المتغيرة.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"20 – 200 kVA","value_ar":"20 – 200 ك.ف.أ"},{"label_en":"Storage","label_ar":"التخزين","value_en":"LiFePO4 battery bank, sized per site","value_ar":"بطاريات ليثيوم فوسفات الحديد حسب الموقع"},{"label_en":"Typical fuel saving","label_ar":"التوفير المعتاد في الوقود","value_en":"Up to 50% on low-load sites","value_ar":"حتى 50% في المواقع منخفضة الحمل"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$]::text[],90,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$solar-hybrid-power-system-10-100kva$q$,$q$Solar-Hybrid Power System 10–100 kVA$q$,$q$نظام طاقة هجين بالطاقة الشمسية 10–100 كيلو فولت أمبير$q$,10,100,null,$q$solar$q$,$q$PV array, battery storage and a backup diesel generator integrated under one controller — for farms, remote camps and off-grid sites across the GCC and Africa.$q$,$q$ألواح شمسية وبطاريات تخزين ومولد ديزل احتياطي تحت وحدة تحكم واحدة، للمزارع والمخيمات النائية والمواقع غير المتصلة بالشبكة في الخليج وأفريقيا.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"10 – 100 kVA","value_ar":"10 – 100 ك.ف.أ"},{"label_en":"Sources","label_ar":"مصادر الطاقة","value_en":"PV + battery + diesel backup","value_ar":"ألواح شمسية + بطاريات + ديزل احتياطي"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$]::text[],100,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$ats_panel$q$,$q$ats-panel-63a-400a$q$,$q$Automatic Transfer Switch Panel 63–400 A$q$,$q$لوحة تحويل أوتوماتيكي ATS من 63 إلى 400 أمبير$q$,10,275,null,null,$q$Wall- or floor-mounted ATS panels that switch your load from mains to generator in seconds when power fails — and back again when it returns. Motorised changeover or contactor based, 3- or 4-pole.$q$,$q$لوحات ATS جدارية أو أرضية تنقل الحمل من الكهرباء العامة إلى المولد خلال ثوانٍ عند انقطاع التيار، وتعيده تلقائياً عند عودته. بمفتاح تحويل مُحرّك أو كونتاكتور، 3 أو 4 أقطاب.$q$,$q$[{"label_en":"Current rating","label_ar":"التيار المقنن","value_en":"63 – 400 A","value_ar":"63 – 400 أمبير"},{"label_en":"Poles","label_ar":"الأقطاب","value_en":"3P or 4P (switched neutral)","value_ar":"3 أو 4 أقطاب (فصل التعادل)"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Auto mains-failure with adjustable timers","value_ar":"كشف انقطاع تلقائي مع مؤقتات قابلة للضبط"},{"label_en":"Enclosure","label_ar":"الغلاف","value_en":"IP54 powder-coated steel (IP65 option)","value_ar":"حديد مطلي IP54 (خيار IP65)"},{"label_en":"Testing","label_ar":"الاختبار","value_en":"Factory function-tested before dispatch","value_ar":"مختبرة وظيفياً قبل الشحن"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/ats-panel.svg$q$]::text[],110,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$ats_panel$q$,$q$ats-panel-630a-4000a$q$,$q$High-Current ATS Panel 630–4000 A$q$,$q$لوحة ATS للتيارات العالية من 630 إلى 4000 أمبير$q$,276,2770,null,null,$q$Floor-standing ATS and ACB-based changeover panels for industrial plants, hospitals and towers — with metering, bypass and multi-source (mains/generator/generator) logic.$q$,$q$لوحات تحويل أرضية بقواطع ACB للمصانع والمستشفيات والأبراج، مع قياس رقمي وخيار تجاوز (Bypass) ومنطق تحويل بين عدة مصادر (كهرباء/مولد/مولد).$q$,$q$[{"label_en":"Current rating","label_ar":"التيار المقنن","value_en":"630 – 4000 A","value_ar":"630 – 4000 أمبير"},{"label_en":"Switching device","label_ar":"جهاز التحويل","value_en":"Motorised ACB pair or open-transition ATS","value_ar":"زوج قواطع ACB مُحرّكة أو ATS انتقال مفتوح"},{"label_en":"Metering","label_ar":"القياس","value_en":"Multifunction meter, Modbus","value_ar":"عداد متعدد الوظائف، Modbus"},{"label_en":"Form of separation","label_ar":"نوع الفصل الداخلي","value_en":"Up to Form 4b","value_ar":"حتى Form 4b"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/ats-panel.svg$q$,$q$/images/products/switchgear.svg$q$]::text[],120,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$switchgear$q$,$q$low-voltage-switchgear-panel$q$,$q$Low Voltage Switchgear Panel up to 6300 A$q$,$q$لوحة مفاتيح جهد منخفض حتى 6300 أمبير$q$,null,null,null,null,$q$Main LV switchboards built around ACB incomers and MCCB feeders for buildings, plants and infrastructure — configured to your single-line diagram and local authority requirements.$q$,$q$لوحات توزيع رئيسية للجهد المنخفض بقواطع ACB للمداخل وMCCB للمخارج، للمباني والمصانع والبنية التحتية، وتُجهّز وفق المخطط أحادي الخط ومتطلبات هيئة الكهرباء المحلية.$q$,$q$[{"label_en":"Rated current","label_ar":"التيار المقنن","value_en":"Up to 6300 A","value_ar":"حتى 6300 أمبير"},{"label_en":"Short-circuit rating","label_ar":"تحمّل القصر","value_en":"Up to 100 kA / 1 s (design dependent)","value_ar":"حتى 100 ك.أ / 1 ث (حسب التصميم)"},{"label_en":"Standard","label_ar":"المعيار","value_en":"Designed to IEC 61439","value_ar":"مصممة وفق IEC 61439"},{"label_en":"Form of separation","label_ar":"نوع الفصل الداخلي","value_en":"Form 2 to Form 4b","value_ar":"من Form 2 إلى Form 4b"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/switchgear.svg$q$]::text[],130,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$switchgear$q$,$q$generator-control-amf-panel$q$,$q$Generator Control & AMF Panel$q$,$q$لوحة تحكم المولد والتشغيل التلقائي AMF$q$,10,2500,null,null,$q$Stand-alone generator control and auto mains-failure panels with remote start, protection and SMS/Ethernet monitoring — ideal for retrofitting older sets.$q$,$q$لوحات تحكم مستقلة للمولدات مع تشغيل تلقائي عند انقطاع الكهرباء، وتشغيل عن بُعد، وحماية ومراقبة عبر الرسائل أو الشبكة، مثالية لتحديث المولدات القديمة.$q$,$q$[{"label_en":"Controllers","label_ar":"وحدات التحكم","value_en":"Deep Sea, ComAp, SmartGen","value_ar":"Deep Sea وComAp وSmartGen"},{"label_en":"Monitoring","label_ar":"المراقبة","value_en":"Ethernet / GSM / Modbus","value_ar":"شبكة / GSM / Modbus"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/ats-panel.svg$q$]::text[],140,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$mdb$q$,$q$main-distribution-board-mdb$q$,$q$Main Distribution Board (MDB) up to 4000 A$q$,$q$لوحة التوزيع الرئيسية MDB حتى 4000 أمبير$q$,null,null,null,null,$q$MDBs, SMDBs and DBs for villas, towers, warehouses and factories — busbar-based, fully labelled and supplied with test certificates ready for utility inspection.$q$,$q$لوحات توزيع رئيسية وفرعية للفلل والأبراج والمستودعات والمصانع، بقضبان نحاسية ومُعلّمة بالكامل ومع شهادات اختبار جاهزة لفحص هيئة الكهرباء.$q$,$q$[{"label_en":"Rated current","label_ar":"التيار المقنن","value_en":"100 – 4000 A","value_ar":"100 – 4000 أمبير"},{"label_en":"Busbar","label_ar":"القضبان","value_en":"Tinned copper, sized per design","value_ar":"نحاس مقصدر حسب التصميم"},{"label_en":"Types","label_ar":"الأنواع","value_en":"MDB, SMDB, DB, capacitor bank","value_ar":"MDB وSMDB وDB ولوحات مكثفات"},{"label_en":"Utility approval","label_ar":"اعتماد الهيئة","value_en":"Built to DEWA / SEWA / ADDC / SEC requirements on request","value_ar":"حسب متطلبات ديوا / سيوا / أدك / السعودية للكهرباء عند الطلب"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/mdb.svg$q$]::text[],150,true) on conflict (slug) do nothing;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$sync_panel$q$,$q$generator-synchronizing-panel$q$,$q$Generator Synchronizing Panel$q$,$q$لوحة تزامن المولدات$q$,200,10000,null,null,$q$Run two or more generators in parallel as one power plant — load sharing, load-demand start/stop and mains synchronisation for redundancy and fuel efficiency.$q$,$q$تشغيل مولدين أو أكثر على التوازي كمحطة طاقة واحدة، مع توزيع الأحمال وتشغيل/إيقاف حسب الطلب والتزامن مع الشبكة لتحقيق الاعتمادية وتوفير الوقود.$q$,$q$[{"label_en":"Configuration","label_ar":"التكوين","value_en":"2 – 16 generators in parallel","value_ar":"من 2 إلى 16 مولداً على التوازي"},{"label_en":"Controllers","label_ar":"وحدات التحكم","value_en":"Deep Sea DSE8610 / ComAp InteliGen","value_ar":"Deep Sea DSE8610 / ComAp InteliGen"},{"label_en":"Functions","label_ar":"الوظائف","value_en":"Load sharing, load-demand, mains paralleling","value_ar":"توزيع الأحمال، التشغيل حسب الطلب، التوازي مع الشبكة"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/sync-panel.svg$q$]::text[],160,true) on conflict (slug) do nothing;
